package com.fasterxml.jackson.databind;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import java.io.*;
import java.io.Closeable;
import java.io.IOException;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.*;

/**
 * Unit tests for MappingIterator#nextValue()
 * Note: Since MappingIterator is a complex class with protected fields and internal state,
 * we use a subclass or Mockito to simulate the internal state required to trigger branches.
 */
public class MappingIterator_nextValue_TriageGen1Test {

    @Mock
    private JsonParser _parser;

    @Mock
    private Deserializer _deserializer;

    @Mock
    private Object _context;

    private TestMappingIterator<String> iterator;

    // A testable subclass to expose protected/private fields and simulate internal state
    private static class TestMappingIterator<T> extends MappingIterator<T> {
        boolean _hasNextChecked = false;
        boolean _hasNextValueResult = true;
        JsonParser _parser;
        Deserializer _deserializer;
        Object _context;
        T _updatedValue = null;

        public TestMappingIterator(JsonParser parser, Deserializer deserializer, Object context) {
            this._parser = parser;
            this._deserializer = deserializer;
            this._context = context;
        }

        @Override
        public boolean hasNextValue() throws IOException {
            return _hasNextValueResult;
        }

        @Override
        protected T _throwNoSuchElement() {
            throw new java.util.NoSuchElementException("No more elements");
        }

        // Accessors to manipulate state for coverage
        public void setHasNextChecked(boolean val) { this._hasNextChecked = val; }
        public void setHasNextValueResult(boolean val) { this._hasNextValueResult = val; }
        public void setParser(JsonParser parser) { this._parser = parser; }
        public void setDeserializer(Deserializer deserializer) { this._deserializer = deserializer; }
        public void setUpdatedValue(T val) { this._updatedValue = val; }
    }

    // Mock interface for Deserializer since it's used in the logic
    interface Deserializer {
        <T> T deserialize(JsonParser p, Object ctx) throws IOException;
        <T> void deserialize(JsonParser p, Object ctx, T reusable) throws IOException;
    }

    @Before
    public void setUp() {
        MockitoAnnotations.initMocks(this);
        iterator = new TestMappingIterator<>(_parser, _deserializer, _context);
    }

    @Test
    public void testNextValue_NoHasNextChecked_NoHasNextValue() throws IOException {
        iterator.setHasNextChecked(false);
        iterator.setHasNextValueResult(false);

        try {
            iterator.nextValue();
        } catch (java.util.NoSuchElementException e) {
            // Expected
        }
    }

    @Test
    public void testNextValue_NoHasNextChecked_ParserNull() throws IOException {
        iterator.setHasNextChecked(false);
        iterator.setHasNextValueResult(true);
        iterator.setParser(null);

        try {
            iterator.nextValue();
        } catch (java.util.NoSuchElementException e) {
            // Expected
        }
    }

    @Test
    public void testNextValue_HasNextChecked_ParserNull() throws IOException {
        iterator.setHasNextChecked(true);
        iterator.setParser(null);

        try {
            iterator.nextValue();
        } catch (java.util.NoSuchElementException e) {
            // Expected
        }
    }

    @Test
    public void testNextValue_Successful_NewObject() throws IOException {
        iterator.setHasNextChecked(false);
        iterator.setHasNextValueResult(true);
        iterator.setUpdatedValue(null);

        String expected = "testValue";
        when(_deserializer.deserialize(_parser, _context)).thenReturn(expected);

        String result = iterator.nextValue();

        assertEquals(expected, result);
        verify(_parser).clearCurrentToken();
        assertEquals(false, iterator.setHasNextChecked(false) == false ? false : true); // dummy to check state logic
    }

    @Test
    public void testNextValue_Successful_ReusableObject() throws IOException {
        iterator.setHasNextChecked(false);
        iterator.setHasNextValueResult(true);

        String reusable = "reusableValue";
        iterator.setUpdatedValue(reusable);

        doNothing().when(_deserializer).deserialize(_parser, _context, reusable);

        String result = iterator.nextValue();

        assertEquals(reusable, result);
        verify(_deserializer).deserialize(_parser, _context, reusable);
        verify(_parser).clearCurrentToken();
    }

    @Test
    public void testNextValue_IOException_TriggersFinally() throws IOException {
        iterator.setHasNextChecked(false);
        iterator.setHasNextValueResult(true);
        iterator.setUpdatedValue(null);

        when(_deserializer.deserialize(_parser, _context)).thenThrow(new IOException("IO Error"));

        try {
            iterator.nextValue();
        } catch (IOException e) {
            assertEquals("IO Error", e.getMessage());
        }

        // Ensure finally block is executed
        verify(_parser).clearCurrentToken();
    }

    @Test
    public void testNextValue_HasNextCheckedIsTrue_SkipsHasNextValue() throws IOException {
        iterator.setHasNextChecked(true);
        iterator.setHasNextValueResult(false); // Should not be called
        iterator.setUpdatedValue(null);

        when(_deserializer.deserialize(_parser, _context)).thenReturn("val");

        String result = iterator.nextValue();

        assertEquals("val", result);
        verify(iterator, never()).hasNextValue();
        verify(_parser).clearCurrentToken();
    }
}
